package br.com.archlab.simulation.core.v3;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static br.com.archlab.simulation.core.v3.ArchitectureV3.*;
import static br.com.archlab.simulation.core.v3.ExecutionPlanV3.*;
import br.com.archlab.simulation.core.v3.ExecutionPlanV3.Process;
class SynchronousExecutionV3Test {
    static IdentifierV3 id(String v){return new IdentifierV3(v);}static PropertyValueV3.IntegerValue n(long v){return new PropertyValueV3.IntegerValue(v);}
    static Map<Outcome,IdentifierV3> next(Outcome o,String target){return Map.of(o,id(target));}
    static SimulationRequestV3 fixture(Long rootTimeout,Long callTimeout,boolean background,boolean databaseAvailable){
        var components=List.of(new Component(id("client"),id("CLIENT_GENERIC"),"Client",Map.of()),new Component(id("api"),id("API_SERVICE"),"API",Map.of()),new Component(id("db"),id("DATABASE_GENERIC"),"DB",Map.of("processingMs",n(30),"available",new PropertyValueV3.Flag(databaseAvailable))));
        var resources=new ArrayList<Resource>();resources.add(new Resource(id("db-pool"),id("PROCESSING_POOL"),id("db"),Map.of("capacity",n(1))));if(callTimeout!=null)resources.add(new Resource(id("call-policy"),id("POLICY_INSTANCE"),id("api"),Map.of("timeoutMs",n(callTimeout))));
        var endpoints=List.of(new Endpoint(id("client-out"),id("client"),Direction.OUTBOUND,id("HTTP_REST"),List.of(),Map.of()),new Endpoint(id("api-in"),id("api"),Direction.INBOUND,id("HTTP_REST"),List.of(id("api-op")),Map.of()),
                new Endpoint(id("api-out"),id("api"),Direction.OUTBOUND,id("DATABASE_QUERY"),List.of(),Map.of()),new Endpoint(id("db-in"),id("db"),Direction.INBOUND,id("DATABASE_QUERY"),List.of(id("db-op")),Map.of()));
        var rootProps=new HashMap<String,PropertyValueV3>();rootProps.put("latencyMs",n(10));if(rootTimeout!=null)rootProps.put("timeoutMs",n(rootTimeout));
        var relations=List.<Relation>of(new Communication(id("client-api"),id("client-out"),id("api-in"),id("HTTP_REST"),rootProps),new Communication(id("api-db"),id("api-out"),id("db-in"),id("DATABASE_QUERY"),Map.of("latencyMs",n(5))));
        var operations=List.of(new Operation(id("api-op"),id("api"),"API operation",null,null,new Binding(BindingKind.EXECUTION_PLAN,id("api-plan")),List.of()),new Operation(id("db-op"),id("db"),"DB query",null,null,new Binding(BindingKind.NATIVE_BEHAVIOR,id("DATABASE_QUERY")),List.of()));
        var transitions=new EnumMap<Outcome,IdentifierV3>(Outcome.class);transitions.put(background?Outcome.DISPATCHED:Outcome.SUCCESS,id("post"));transitions.put(Outcome.FAILURE,id("fail"));if(!background)transitions.put(Outcome.TIMEOUT,id("fail"));
        var plan=new ExecutionPlanV3(id("api-plan"),id("api-op"),id("pre"),new Limits(100,10),List.of(new Process(id("pre"),new DurationMsV3(20),null,next(Outcome.NEXT,"call")),
                new Call(id("call"),id("api-db"),id("db-op"),background?AwaitCall.NONE:AwaitCall.RESPONSE,callTimeout==null?null:id("call-policy"),transitions),new Delay(id("post"),new DurationMsV3(15),id("done")),new Complete(id("done"),Scope.ACTIVATION,id("ok")),new Fail(id("fail"),Scope.ACTIVATION,id("error"))));
        var architecture=new ArchitectureV3(id("architecture"),"3",components,resources,endpoints,operations,relations,List.of(plan));
        return new SimulationRequestV3(architecture,new SimulationRequestV3.Scenario(id("scenario"),new SimulationRequestV3.Entry(id("client"),id("api-op"),id("client-api"),null),List.of(),Map.of()),new SimulationRequestV3.Options(7,SimulationRequestV3.CompletionMode.DRAIN_ALL,null));
    }
    @Test void nestedCallProduces95MsAndReleasesDatabaseLease(){var request=fixture(null,null,false,true);assertTrue(new ArchitectureValidatorV3(TypeCatalogV3.initial()).validate(request.architecture()).valid());assertTrue(new ExecutionPlanValidatorV3(TypeCatalogV3.initial()).validate(request.architecture(),request.architecture().executionPlans().getFirst()).valid());
        var engine=new SimulationEngineV3(request);var result=engine.run();assertEquals("COMPLETED",engine.control().globalStop());assertEquals(95L,engine.control().principalResponseAt());assertEquals(95,result.current().agenda().nowMs());assertEquals(30,engine.control().processing().get(id("db")));assertEquals(20,engine.control().processing().get(id("api")));
        var resource=(RuntimeEntityV3.Resource)result.current().state().entities().get(id("db-pool"));assertEquals(0L,resource.inUse());assertTrue(result.current().journal().stream().flatMap(c->c.deltas().stream()).anyMatch(d->d.after() instanceof RuntimeEntityV3.Activation a && a.status()==RuntimeEntityV3.ActivationStatus.WAITING));
    }
    @Test void responseAtExactDeadlineWinsAndDoesNotExtendGlobalClockToCancelledTimers(){var engine=new SimulationEngineV3(fixture(95L,null,false,true));engine.run();assertEquals(95L,engine.control().principalResponseAt());assertEquals("SUCCESS",engine.control().principalOutcome());assertEquals("COMPLETED",engine.control().globalStop());}
    @Test void nestedTimeoutCancelsDatabaseAndPropagatesFailure(){var engine=new SimulationEngineV3(fixture(null,10L,false,true));var result=engine.run();assertEquals(50L,engine.control().principalTerminalAt());assertEquals("FAILURE",engine.control().principalOutcome());assertNull(engine.control().principalResponseAt());assertEquals("COMPLETED",engine.control().globalStop());assertEquals(0L,((RuntimeEntityV3.Resource)result.current().state().entities().get(id("db-pool"))).inUse());}
    @Test void rootTimeoutPropagatesCancellationThroughNestedCall(){var engine=new SimulationEngineV3(fixture(40L,null,false,true));var result=engine.run();assertEquals(40L,engine.control().principalTerminalAt());assertEquals("TIMEOUT",engine.control().principalOutcome());assertEquals(40,result.current().agenda().nowMs());assertEquals("COMPLETED",engine.control().globalStop());assertTrue(result.current().state().entities().values().stream().noneMatch(e->e instanceof RuntimeEntityV3.WorkItem w && w.status()==RuntimeEntityV3.WorkItemStatus.PENDING));}
    @Test void fireAndForgetCallKeepsGlobalWorkAfterPrincipalResponse(){var engine=new SimulationEngineV3(fixture(null,null,true,true));engine.run();assertEquals(55L,engine.control().principalResponseAt());assertEquals(70,engine.checkpoint().current().agenda().nowMs());assertEquals("COMPLETED",engine.control().globalStop());}
    @Test void unavailableDatabaseIsSimulatedFailureInsteadOfEngineException(){var engine=new SimulationEngineV3(fixture(null,null,false,false));engine.run();assertEquals(45L,engine.control().principalTerminalAt());assertEquals("FAILURE",engine.control().principalOutcome());assertTrue(engine.checkpoint().current().trace().stream().anyMatch(t->t.kind()==TraceRecordV3.Kind.MESSAGE_DELIVERY_FAILED));}
    @Test void checkpointReexecutionAndJournalReplayAreExact(){var request=fixture(null,null,false,true);var engine=new SimulationEngineV3(request);for(int i=0;i<12;i++)assertTrue(engine.step());var checkpoint=engine.checkpoint();var resumed=SimulationEngineV3.resume(checkpoint);var continued=engine.run();assertEquals(continued,resumed.run());
        assertEquals(continued.current(),AtomicDispatcherV3.replay(continued.initial(),continued.current().journal()));assertEquals(continued,new SimulationEngineV3(request).run());}
    @Test void horizonReturnsInProgressWithoutInventingAResponse(){var original=fixture(null,null,false,true);var request=new SimulationRequestV3(original.architecture(),original.scenario(),new SimulationRequestV3.Options(7,SimulationRequestV3.CompletionMode.UNTIL_HORIZON,25L));var engine=new SimulationEngineV3(request);engine.run();assertEquals("HORIZON_REACHED",engine.control().globalStop());assertNull(engine.control().principalTerminalAt());assertEquals(25,engine.checkpoint().current().agenda().nowMs());}
    @Test void boundedZeroDurationLoopStopsAtPlanLimit(){var original=fixture(null,null,false,true);var loop=new ExecutionPlanV3(id("api-plan"),id("api-op"),id("loop"),new Limits(10,3),List.of(new Delay(id("loop"),DurationMsV3.ZERO,id("loop"))));var a=original.architecture();var architecture=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),a.resources(),a.endpoints(),a.operations(),a.relations(),List.of(loop));var engine=new SimulationEngineV3(new SimulationRequestV3(architecture,original.scenario(),original.options()));engine.run();assertEquals("LIMIT_REACHED",engine.control().globalStop());assertTrue(engine.checkpoint().current().journal().size()<100);}
    @Test void conditionsDistinguishMissingFromNullAndShortCircuit(){var values=Map.<String,PropertyValueV3>of("x",n(3));assertTrue(ConditionsV3.evaluate(new Compare(Comparison.GTE,new Reference("parameters.x"),new Literal(3L)),values));assertFalse(ConditionsV3.evaluate(new Exists(new Reference("missing")),values));assertTrue(ConditionsV3.evaluate(new Compare(Comparison.EQ,new Literal(null),new Literal(null)),values));assertThrows(IllegalArgumentException.class,()->ConditionsV3.evaluate(new Compare(Comparison.EQ,new Reference("missing"),new Literal(null)),values));
        assertFalse(ConditionsV3.evaluate(new Junction(Logical.AND,List.of(new Exists(new Reference("missing")),new Compare(Comparison.GT,new Literal(true),new Literal(3L)))),values));}
    @Test void conditionStepExecutesTrueFalseAndErrorBranches(){for(int variant=0;variant<3;variant++){var original=fixture(null,null,false,true);var old=original.architecture().executionPlans().getFirst();var steps=new ArrayList<>(old.steps());steps.add(new Condition(id("condition"),new Compare(Comparison.EQ,new Reference("parameters.enabled"),new Literal(true)),id("pre"),id("fail"),id("fail")));var plan=new ExecutionPlanV3(old.id(),old.operationId(),id("condition"),old.limits(),steps);var a=original.architecture();var changed=new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),a.resources(),a.endpoints(),a.operations(),a.relations(),List.of(plan));var s=original.scenario();var scenario=new SimulationRequestV3.Scenario(s.id(),s.entry(),s.initialStates(),variant==2?Map.of():Map.of("enabled",new PropertyValueV3.Flag(variant==0)));var engine=new SimulationEngineV3(new SimulationRequestV3(changed,scenario,original.options()));engine.run();assertEquals(variant==0?95L:20L,engine.control().principalTerminalAt());String outcome=variant==0?"TRUE":variant==1?"FALSE":"ERROR";assertTrue(engine.checkpoint().current().trace().stream().anyMatch(t->t.detail() instanceof TraceRecordV3.Step detail && outcome.equals(detail.outcomeCode())));}}
    @Test void unavailableClientFailsBeforeAnyMessageIsSent(){var original=fixture(null,null,false,true);var s=original.scenario();var scenario=new SimulationRequestV3.Scenario(s.id(),s.entry(),List.of(new InitialStateV3.Component(id("client"),false)),s.parameters());var engine=new SimulationEngineV3(new SimulationRequestV3(original.architecture(),scenario,original.options()));engine.run();assertEquals("SOURCE_UNAVAILABLE",engine.control().principalOutcome());assertEquals(0L,engine.control().principalTerminalAt());assertTrue(engine.checkpoint().current().trace().stream().noneMatch(t->t.kind()==TraceRecordV3.Kind.MESSAGE_SENT));}
}
